(() => {
  'use strict';
  const escP = value => { const d = document.createElement('div'); d.textContent = String(value ?? ''); return d.innerHTML; };
  const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
  const hasBn = value => /[\u0980-\u09FF]/.test(String(value || ''));
  const normalize = value => clean(value).toLocaleLowerCase().replace(/[।!?.,:;()\[\]{}"'`]/g, '').replace(/\s+/g, ' ');
  const cacheKey = 'admission-phase2-dictionary-v1';
  const parserKey = 'admission-phase2-parser-draft-v1';
  const dictionaryState = (() => { try { return JSON.parse(localStorage.getItem(cacheKey) || '{}'); } catch (_) { return {}; } })();
  dictionaryState.recent = Array.isArray(dictionaryState.recent) ? dictionaryState.recent : [];
  dictionaryState.favorites = Array.isArray(dictionaryState.favorites) ? dictionaryState.favorites : [];
  dictionaryState.result = dictionaryState.result || null;
  dictionaryState.loading = false; dictionaryState.loadingStage = '';
  dictionaryState.error = '';
  dictionaryState.suggestions = [];
  const saveDictionary = () => { try { localStorage.setItem(cacheKey, JSON.stringify(dictionaryState)); } catch (_) {} };

  function hostOf(url) { try { return new URL(url).hostname.replace(/^www\./, ''); } catch (_) { return 'Web source'; } }
  function validUrl(url) { try { const u = new URL(url); return /^https?:$/.test(u.protocol); } catch (_) { return false; } }
  async function getJson(url, timeout = 8000) {
    const ctrl = new AbortController(); const timer = setTimeout(() => ctrl.abort(), timeout);
    try { const res = await fetch(url, { signal: ctrl.signal, headers: { Accept: 'application/json' }, mode: 'cors' }); if (!res.ok) throw Error('HTTP ' + res.status); return await res.json(); }
    finally { clearTimeout(timer); }
  }
  const googleUrl = q => 'https://www.google.com/search?q=' + encodeURIComponent(q);
  const suggestUrl = q => 'https://suggestqueries.google.com/complete/search?client=firefox&hl=' + (hasBn(q) ? 'bn' : 'en') + '&q=' + encodeURIComponent(q);

  async function loadSuggestions(q) {
    if (!clean(q)) { dictionaryState.suggestions = []; renderDictionary(); return; }
    try { const data = await getJson(suggestUrl(q), 4500); dictionaryState.suggestions = Array.isArray(data?.[1]) ? data[1].filter(Boolean).slice(0, 6) : []; }
    catch (_) { dictionaryState.suggestions = [q + ' meaning', q + ' definition', q + ' synonyms'].slice(0, 3); }
    renderDictionary();
  }
  let suggestionTimer = null;
  window.dictionarySuggest = value => { clearTimeout(suggestionTimer); suggestionTimer = setTimeout(() => loadSuggestions(value), 250); };

  async function fetchDictionaryEntry(q) {
    if (!/^[a-zA-Z][a-zA-Z\s'-]*$/.test(q)) return null;
    try {
      const api = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=bn&dt=t&dt=bd&dt=md&dt=ex&dj=1&q=' + encodeURIComponent(q);
      const data = await getJson(api, 10000);
      const definitions = Array.isArray(data?.definitions) ? data.definitions : [];
      const meanings = definitions.flatMap(group => (group.entry || []).map(item => ({
        partOfSpeech: group.pos || 'word', definition: clean(item.gloss), example: clean(item.example), synonyms: [], antonyms: []
      })));
      const dictionaryGroups = Array.isArray(data?.dict) ? data.dict : [];
      const banglaTerms = uniqueWords(dictionaryGroups.flatMap(group => group.terms || []), q).slice(0, 16);
      const word = clean(dictionaryGroups[0]?.base_form || q);
      const entry = { word, meanings, phonetic: '' };
      return { entry, meanings, banglaMeaning: banglaTerms.join(', '), googleExamples: Array.isArray(data?.examples?.example) ? data.examples.example.map(x => clean(String(x.text || '').replace(/<[^>]*>/g, ''))).filter(Boolean) : [] };
    } catch (_) { return null; }
  }
  async function fetchDatamuse(q) {
    try {
      const [syn, ant] = await Promise.all([
        getJson('https://api.datamuse.com/words?rel_syn=' + encodeURIComponent(q) + '&max=12'),
        getJson('https://api.datamuse.com/words?rel_ant=' + encodeURIComponent(q) + '&max=12')
      ]);
      return { synonyms: Array.isArray(syn) ? syn.map(x => x.word).filter(Boolean) : [], antonyms: Array.isArray(ant) ? ant.map(x => x.word).filter(Boolean) : [] };
    } catch (_) { return { synonyms: [], antonyms: [] }; }
  }
  async function fetchWikipedia(q, lang) {
    try {
      const api = 'https://' + lang + '.wikipedia.org/w/api.php?action=opensearch&search=' + encodeURIComponent(q) + '&limit=4&namespace=0&format=json&origin=*';
      const data = await getJson(api); const titles = data?.[1] || []; const urls = data?.[3] || [];
      const rows = await Promise.all(titles.slice(0, 4).map(async (title, i) => { try { const s = await getJson('https://' + lang + '.wikipedia.org/api/rest_v1/page/summary/' + encodeURIComponent(title.replace(/\s+/g, '_'))); return s?.extract ? { title: s.title || title, snippet: s.extract, url: s.content_urls?.desktop?.page || urls[i], source: lang === 'bn' ? 'বাংলা Wikipedia' : 'Wikipedia' } : null; } catch (_) { return null; } }));
      return rows.filter(x => x && validUrl(x.url));
    } catch (_) { return []; }
  }
  async function fetchDdg(q) {
    try {
      const d = await getJson('https://api.duckduckgo.com/?q=' + encodeURIComponent(q) + '&format=json&no_html=1&skip_disambig=1');
      const rows = []; if (d?.AbstractText) rows.push({ title: d.Heading || q, snippet: d.AbstractText, url: d.AbstractURL, source: d.AbstractSource || 'DuckDuckGo' });
      return rows.concat((d?.RelatedTopics || []).flatMap(x => x.Topics || [x]).filter(x => x.Text && x.FirstURL).slice(0, 4).map(x => ({ title: clean(x.Text).split(' - ')[0], snippet: x.Text, url: x.FirstURL, source: 'DuckDuckGo' })));
    } catch (_) { return []; }
  }
  function uniqueWords(values, q) { return [...new Set(values.map(clean).filter(x => x && normalize(x) !== normalize(q) && !x.includes('undefined') && !x.includes('null')))]; }
  async function buildDictionaryResult(query) {
    const q = clean(query); const bn = hasBn(q);
    const [entryData, relations, wiki, ddg] = await Promise.all([fetchDictionaryEntry(q), fetchDatamuse(q), fetchWikipedia(q, bn ? 'bn' : 'en'), fetchDdg(q)]);
    let entry = entryData?.entry; let meanings = entryData?.meanings || [];
    let synonyms = uniqueWords([...meanings.flatMap(x => x.synonyms || []), ...relations.synonyms], q);
    let antonyms = uniqueWords([...meanings.flatMap(x => x.antonyms || []), ...relations.antonyms], q);
    const webSources = [...wiki, ...ddg].filter(x => validUrl(x.url));
    if (!entry && !webSources.length) throw Error('No public result found');
    let banglaMeaning = '';
    if (bn) banglaMeaning = webSources.find(x => hasBn(x.snippet))?.snippet || '';
    if (!banglaMeaning && entry?.meanings?.[0]?.definitions?.[0]?.definition) {
      try { const translated = await getJson('https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=bn&dt=t&q=' + encodeURIComponent(entry.meanings[0].definitions[0].definition)); banglaMeaning = translated?.[0]?.map(x => x?.[0]).filter(Boolean).join('') || ''; } catch (_) {}
    }
    const allDefinitions = uniqueWords(meanings.map(x => x.definition), q);
    const examples = uniqueWords([...(entryData?.googleExamples || []), ...meanings.map(x => x.example).filter(Boolean)], q).slice(0, 8);
    const pos = uniqueWords(meanings.map(x => x.partOfSpeech), q)[0] || (bn ? 'শব্দ / ধারণা' : 'word');
    return { query: q, word: entry?.word || q, phonetic: entry?.phonetic || entry?.phonetics?.find(x => x.text)?.text || '', banglaMeaning: banglaMeaning || (bn ? 'বিশ্বস্ত প্রকাশ্য উৎসে বাংলা ব্যাখ্যা পাওয়া যায়নি। নিচের উৎসগুলো দেখুন।' : ''), partOfSpeech: pos, definition: allDefinitions[0] || webSources[0]?.snippet || 'Open a source link for the full definition.', meanings: allDefinitions.slice(0, 8), examples: examples.slice(0, 8), synonyms: synonyms.slice(0, 12), antonyms: antonyms.slice(0, 12), sources: [{ title: 'Google Search', url: googleUrl(q), source: 'Google' }, ...webSources.map(x => ({ title: x.title, url: x.url, source: x.source }))].filter(x => validUrl(x.url)).slice(0, 10), language: bn ? 'bn' : 'en', savedAt: Date.now() };
  }
  function dictionaryHistory() { return dictionaryState.recent.slice(0, 8); }
  function isFavorite(word) { return dictionaryState.favorites.some(x => normalize(x.word || x) === normalize(word)); }
  function renderDictionary() {
    const r = dictionaryState.result; const suggestions = dictionaryState.suggestions || [];
    const suggestionsHtml = suggestions.length ? `<div class="p2-suggestions">${suggestions.map(x => `<button type="button" onclick="dictionaryChoose(${JSON.stringify(x)})">${escP(x)}</button>`).join('')}</div>` : '';
    const status = dictionaryState.loading ? `<div class="p2-status">${escP(dictionaryState.loadingStage || '🔎 Searching…')}</div>` : dictionaryState.error ? `<div class="p2-error"><strong>Could not find a reliable public result.</strong><p>${escP(dictionaryState.error)}</p><button class="p2-secondary" type="button" onclick="retryDictionary()">Retry</button></div>` : '';
    const result = r ? `<article class="p2-dict-result"><div class="p2-word-row"><div><div class="p2-kicker">SMART DICTIONARY · ${r.language === 'bn' ? 'বাংলা ফলাফল' : 'WEB RESULT'}</div><h2>${escP(r.word)}</h2><p class="p2-phonetic">${escP(r.phonetic || 'Pronunciation unavailable')}</p></div><button type="button" class="p2-favorite ${isFavorite(r.word) ? 'active' : ''}" onclick="toggleDictionaryFavorite()">${isFavorite(r.word) ? '★' : '☆'} Favorite</button></div><div class="p2-dict-grid"><section><h3>বাংলা অর্থ</h3><p>${escP(r.banglaMeaning || 'No Bengali meaning found in public sources.')}</p></section><section><h3>Part of speech</h3><p>${escP(r.partOfSpeech)}</p></section><section class="p2-wide"><h3>English definition</h3><p>${escP(r.definition)}</p></section><section><h3>Multiple meanings</h3>${r.meanings.length ? `<ol>${r.meanings.map(x => `<li>${escP(x)}</li>`).join('')}</ol>` : '<p>No additional verified meaning found.</p>'}</section><section><h3>Examples</h3>${r.examples.length ? r.examples.map(x => `<p class="p2-example">“${escP(x)}”</p>`).join('') : '<p>No public example found.</p>'}</section><section><h3>5+ synonyms</h3><p>${escP(r.synonyms.length ? r.synonyms.join(', ') : 'No verified synonyms found in the available sources.')}</p></section><section><h3>5+ antonyms</h3><p>${escP(r.antonyms.length ? r.antonyms.join(', ') : 'No verified antonyms found in the available sources.')}</p></section></div><div class="p2-sources"><h3>Source links</h3>${r.sources.map(s => `<a href="${escP(s.url)}" target="_blank" rel="noopener noreferrer"><strong>${escP(s.title)}</strong><small>${escP(s.source)} · ${escP(hostOf(s.url))}</small></a>`).join('')}</div></article>` : '';
    const recent = dictionaryHistory();
    renderShell(`<div class="p2-page"><div class="p2-head"><button class="p2-back" onclick="navigate('dashboard')">← Dictionary</button><div class="p2-kicker">PUBLIC WEB LEXICON</div><h1>Smart Dictionary</h1><p>Google-powered live vocabulary lookup with structured results from verified public sources. এটি AI-generated dictionary নয়।</p></div><form class="p2-search" onsubmit="searchDictionary(event)"><input id="p2DictInput" value="${escP(dictionaryState.query || '')}" oninput="dictionarySuggest(this.value)" autocomplete="off" placeholder="Search any English word…" required><button class="p2-primary" type="submit">${dictionaryState.loading ? 'Searching…' : 'Search'}</button>${suggestionsHtml}</form>${status}${result}<section class="p2-recent"><div class="p2-section-title"><h3>Recent searches</h3><span>Offline cache available</span></div>${recent.length ? recent.map(x => `<button type="button" onclick="dictionaryChoose(${JSON.stringify(x.word)})"><span>${escP(x.word)}</span><small>${x.language === 'bn' ? 'বাংলা' : 'English'}</small></button>`).join('') : '<p class="p2-muted">Searches will appear here and remain available offline.</p>'}</section></div>`, { topbar: false });
  }
  window.renderDictionary = renderDictionary;
  window.dictionaryChoose = word => { const input = document.getElementById('p2DictInput'); if (input) { input.value = word; searchDictionary({ preventDefault() {} }); } };
  window.searchDictionary = async event => { event?.preventDefault?.(); const input = document.getElementById('p2DictInput'); const q = clean(input?.value || dictionaryState.query || ''); if (!q || dictionaryState.loading) { if (!q) { dictionaryState.error = 'অনুগ্রহ করে একটি ইংরেজি শব্দ লিখুন।'; renderDictionary(); } return; } dictionaryState.query = q; dictionaryState.loading = true; dictionaryState.loadingStage = '🔎 Searching…'; dictionaryState.error = ''; dictionaryState.suggestions = []; renderDictionary(); try { dictionaryState.loadingStage = '🌐 Collecting…'; renderDictionary(); const result = await buildDictionaryResult(q); dictionaryState.loadingStage = '📖 Preparing…'; renderDictionary(); dictionaryState.result = result; dictionaryState.recent = [result, ...dictionaryState.recent.filter(x => normalize(x.word) !== normalize(result.word))].slice(0, 12); saveDictionary(); } catch (_) { dictionaryState.result = null; dictionaryState.error = 'নির্ভরযোগ্য তথ্য পাওয়া যায়নি। শব্দটির বানান যাচাই করে আবার চেষ্টা করুন।'; } finally { dictionaryState.loading = false; dictionaryState.loadingStage = ''; saveDictionary(); renderDictionary(); } };
  window.retryDictionary = () => { if (dictionaryState.query) searchDictionary({ preventDefault() {} }); };
  window.toggleDictionaryFavorite = () => { const r = dictionaryState.result; if (!r) return; const index = dictionaryState.favorites.findIndex(x => normalize(x.word) === normalize(r.word)); if (index >= 0) dictionaryState.favorites.splice(index, 1); else dictionaryState.favorites.unshift(r); saveDictionary(); renderDictionary(); };

  const parser = { raw: '', rows: [], subjectId: '', topicId: '', format: 'text', errors: [] };
  function parseAnswer(value) { const s = clean(value).toLocaleLowerCase(); const map = { a: 0, b: 1, c: 2, d: 3, 'ক': 0, 'খ': 1, 'গ': 2, 'ঘ': 3, '১': 0, '২': 1, '৩': 2, '৪': 3, '1': 0, '2': 1, '3': 2, '4': 3 }; const key = s.replace(/[.)।:：\s]/g, '').slice(0, 1); if (Object.prototype.hasOwnProperty.call(map, key)) return map[key]; const n = Number(s); return Number.isInteger(n) && n >= 1 && n <= 4 ? n - 1 : -1; }
  const optionMatch = line => line.match(/^\s*(A|B|C|D|ক|খ|গ|ঘ)\s*[).:：।-]\s*(.+)$/i);
  const answerMatch = line => line.match(/^\s*(?:answer|ans|correct answer|উত্তর|সঠিক উত্তর|ঠিক উত্তর)\s*[:：=\-]?\s*(.+)$/i);
  function splitBlocks(text) {
    const normalizedText = String(text || '').replace(/\r/g, '').trim(); if (!normalizedText) return [];
    const starts = /(?=^\s*(?:Q(?:uestion)?\s*)?(?:\d{1,4}|[০-৯]{1,4})\s*[).:：-]\s*|^\s*(?:প্রশ্ন)\s*(?:\d{1,4}|[০-৯]{1,4})\s*[).:：-]\s*)/gim;
    const blocks = normalizedText.split(starts).map(x => String(x || '').trim()).filter(Boolean); return blocks.length ? blocks : normalizedText.split(/\n\s*\n+/).map(x => String(x || '').trim()).filter(Boolean);
  }
  function parseBlock(block, index) {
    const lines = block.split('\n').map(clean).filter(Boolean); let questionLines = []; let options = ['', '', '', '']; let answer = -1; let answerLine = -1; let explanation = '';
    lines.forEach((line, i) => { const am = answerMatch(line); if (am) { answer = parseAnswer(am[1]); answerLine = i; return; } if (/^(?:explanation|ব্যাখ্যা)\s*[:：]/i.test(line)) { explanation = clean(line.replace(/^[^:：]+[:：]\s*/i, '')); return; } const om = optionMatch(line); if (om) { const idx = parseAnswer(om[1]); if (idx >= 0) options[idx] = clean(om[2]); return; } if (answerLine < 0) questionLines.push(line); else if (!explanation) explanation = line; });
    const fallbackOptions = lines.filter(x => /^\s*[-•]\s+/.test(x)).map(x => clean(x.replace(/^\s*[-•]\s+/, ''))).slice(0, 4); if (options.filter(Boolean).length < 4 && fallbackOptions.length === 4) options = fallbackOptions;
    const issues = []; if (!questionLines.length) issues.push('Missing question'); if (options.some(x => !x)) issues.push('Missing one or more options A–D'); if (answer < 0) issues.push('Missing or unrecognized answer');
    const question = clean(questionLines.join(' ').replace(/^\s*(?:Q(?:uestion)?\s*)?(?:\d{1,4}|[০-৯]{1,4})\s*[).:：-]\s*/i, '').replace(/^প্রশ্ন\s*(?:\d{1,4}|[০-৯]{1,4})\s*[).:：-]\s*/i, ''));
    return { id: 'parsed-' + Date.now().toString(36) + '-' + index, question, options, correctAnswer: answer, answer, explanation, subjectId: parser.subjectId || '', topicId: parser.topicId || '', difficulty: 'medium', source: 'pasted parser', issues, approved: false, duplicate: false, duplicateId: '', keep: true };
  }
  function parseInput(text) { const blocks = splitBlocks(text); return blocks.slice(0, 1000).map((b, i) => parseBlock(b, i)); }
  function duplicateRows(rows) { const existing = new Map(CACHE.questions.map(q => [normalize(q.question), q])); const seen = new Map(); rows.forEach(row => { const key = normalize(row.question); if (key && existing.has(key)) { row.duplicate = true; row.duplicateId = existing.get(key).id; row.issues.push('Duplicate of an existing question'); } if (key && seen.has(key)) { row.duplicate = true; row.duplicateId = seen.get(key); row.issues.push('Duplicate in this paste'); } else if (key) seen.set(key, row.id); }); }
  function parserSubjects() { return CACHE.subjects.map(s => `<option value="${escP(s.id)}" ${parser.subjectId === s.id ? 'selected' : ''}>${escP(s.name)}</option>`).join(''); }
  function parserTopics() { return CACHE.topics.filter(t => !parser.subjectId || t.subjectId === parser.subjectId).map(t => `<option value="${escP(t.id)}" ${parser.topicId === t.id ? 'selected' : ''}>${escP(t.name)}</option>`).join(''); }
  function renderParserHome() { renderShell(`<div class="p2-page"><div class="p2-head"><button class="p2-back" onclick="navigate('question-bank')">← Question Bank</button><div class="p2-kicker">BULK MCQ WORKFLOW</div><h1>Question Parser</h1><p>Paste up to 1,000 Bengali or English MCQs, review every row, then approve them into the same Question Bank.</p></div><div class="p2-parser-tools"><button class="p2-tool-card" type="button" onclick="parserSetMode('paste')"><strong>📋 Paste MCQs</strong><small>Plain text, numbered, Bengali or English options</small></button><button class="p2-tool-card" type="button" onclick="parserImportFile()"><strong>📂 Import file</strong><small>JSON, TXT, or CSV</small></button><button class="p2-tool-card" type="button" onclick="exportQuestionBank('json')"><strong>⇩ Export JSON</strong><small>Download the current Question Bank</small></button><button class="p2-tool-card" type="button" onclick="exportQuestionBank('csv')"><strong>⇩ Export CSV</strong><small>Download questions as a spreadsheet</small></button></div><div class="p2-parser-note"><strong>Accepted answers:</strong> Answer: B · Ans: D · উত্তর: খ · সঠিক উত্তর: C<br><strong>Accepted options:</strong> A–D and ক–ঘ. Missing fields are flagged before anything is saved.</div></div>`, { topbar: false }); }
  function renderParserPaste() { renderShell(`<div class="p2-page"><div class="p2-head"><button class="p2-back" onclick="renderParserHome()">← Parser</button><div class="p2-kicker">STEP 1 OF 2</div><h1>Paste and structure</h1><p>Use blank lines or numbered question starts. The parser never saves until approval.</p></div><div class="p2-parser-assignment"><label>Subject<select id="p2ParserSubject" onchange="parser.subjectId=this.value;parser.topicId='';renderParserPaste()"><option value="">Choose subject</option>${parserSubjects()}</select></label><label>Topic<select id="p2ParserTopic" onchange="parser.topicId=this.value"><option value="">Choose topic</option>${parserTopics()}</select></label></div><textarea id="p2ParserInput" class="p2-textarea" rows="15" placeholder="1. বাংলাদেশের রাজধানী কোনটি?\nক) ঢাকা\nখ) চট্টগ্রাম\nগ) খুলনা\nঘ) রাজশাহী\nউত্তর: ক\nব্যাখ্যা: ঢাকা বাংলাদেশের রাজধানী।">${escP(parser.raw)}</textarea><div class="p2-parser-actions"><button class="p2-secondary" type="button" onclick="renderParserHome()">Cancel</button><button class="p2-primary" type="button" onclick="runQuestionParser()">Preview questions</button></div></div>`, { topbar: false }); }
  function renderParserPreview() { const valid = parser.rows.filter(r => !r.issues.length && r.keep).length; const errors = parser.rows.filter(r => r.issues.length).length; renderShell(`<div class="p2-page"><div class="p2-head"><button class="p2-back" onclick="parserSetMode('paste')">← Edit input</button><div class="p2-kicker">STEP 2 OF 2</div><h1>Preview and approve</h1><p>${parser.rows.length} parsed · ${valid} ready · ${errors} with issues. Edit or delete any row before saving.</p></div><div class="p2-parser-assignment"><label>Subject<select onchange="parser.subjectId=this.value;parser.topicId='';parser.rows.forEach(x=>x.subjectId=this.value);renderParserPreview()"><option value="">Choose subject</option>${parserSubjects()}</select></label><label>Topic<select onchange="parser.topicId=this.value;parser.rows.forEach(x=>x.topicId=this.value)"><option value="">Choose topic</option>${parserTopics()}</select></label></div><div class="p2-preview-actions"><button class="p2-secondary" type="button" onclick="exportParsed('json')">Export JSON</button><button class="p2-secondary" type="button" onclick="exportParsed('csv')">Export CSV</button><button class="p2-primary" type="button" onclick="approveParsedQuestions()">Approve ${valid} questions</button></div><div class="p2-preview-list">${parser.rows.map((r, i) => `<article class="p2-preview-card ${r.issues.length ? 'has-issues' : ''} ${r.keep ? '' : 'removed'}"><div class="p2-preview-top"><strong>#${i + 1}</strong><span>${r.issues.length ? '⚠ Needs attention' : r.duplicate ? '↻ Duplicate' : '✓ Ready'}</span><button type="button" onclick="editParsedRow(${i})">✏️ Edit</button><button type="button" onclick="deleteParsedRow(${i})">🗑 Delete</button></div><h3>${escP(r.question || 'Missing question')}</h3><div class="p2-options">${r.options.map((x, j) => `<span class="${j === r.correctAnswer ? 'correct' : ''}">${String.fromCharCode(65 + j)}. ${escP(x || 'Missing')}</span>`).join('')}</div><p class="p2-preview-meta">Answer: ${r.correctAnswer >= 0 ? String.fromCharCode(65 + r.correctAnswer) : 'Missing'} · ${r.explanation ? 'Explanation saved' : 'No explanation'} · ${r.duplicate ? 'Duplicate detected' : 'New question'}</p>${r.issues.length ? `<div class="p2-issues">${r.issues.map(x => `<div>• ${escP(x)}</div>`).join('')}</div>` : ''}</article>`).join('')}</div></div>`, { topbar: false }); }
  window.parserSetMode = mode => { parser.format = mode; if (mode === 'paste') renderParserPaste(); else renderParserHome(); };
  function syncParserAssignment() { parser.subjectId = document.getElementById('p2ParserSubject')?.value || parser.subjectId || ''; parser.topicId = document.getElementById('p2ParserTopic')?.value || parser.topicId || ''; parser.rows.forEach(row => { row.subjectId = parser.subjectId; row.topicId = parser.topicId; }); }
  window.runQuestionParser = () => { syncParserAssignment(); parser.raw = document.getElementById('p2ParserInput')?.value || ''; parser.rows = parseInput(parser.raw); parser.rows.forEach(row => { row.subjectId = parser.subjectId; row.topicId = parser.topicId; }); duplicateRows(parser.rows); renderParserPreview(); };
  window.editParsedRow = index => { const r = parser.rows[index]; if (!r) return; openModal(`<h3>Edit parsed question</h3><label class="flabel">Question</label><textarea id="p2EditQuestion" rows="4">${escP(r.question)}</textarea><label class="flabel">Options A–D</label>${r.options.map((x,i) => `<input class="input" id="p2EditOpt${i}" value="${escP(x)}" placeholder="Option ${String.fromCharCode(65+i)}">`).join('')}<label class="flabel">Correct answer</label><select id="p2EditAnswer">${['A','B','C','D'].map((x,i) => `<option value="${i}" ${r.correctAnswer === i ? 'selected' : ''}>${x}</option>`).join('')}</select><label class="flabel">Explanation</label><textarea id="p2EditExplanation" rows="3">${escP(r.explanation)}</textarea><button class="btn" style="margin-top:14px" onclick="saveParsedEdit(${index})">Save row</button>`); };
  window.saveParsedEdit = index => { const r = parser.rows[index]; if (!r) return; r.question = clean(document.getElementById('p2EditQuestion')?.value); r.options = [0,1,2,3].map(i => clean(document.getElementById('p2EditOpt'+i)?.value)); r.correctAnswer = Number(document.getElementById('p2EditAnswer')?.value); r.answer = r.correctAnswer; r.explanation = clean(document.getElementById('p2EditExplanation')?.value); r.issues = []; if (!r.question) r.issues.push('Missing question'); if (r.options.some(x => !x)) r.issues.push('Missing one or more options A–D'); duplicateRows(parser.rows); closeModal(); renderParserPreview(); };
  window.deleteParsedRow = index => { if (parser.rows[index]) parser.rows[index].keep = false; renderParserPreview(); };
  async function saveQuestionRow(r) { const q = { id: uid(), subjectId: r.subjectId, topicId: r.topicId, question: r.question, options: r.options, answer: r.correctAnswer, answerIndex: r.correctAnswer, explanation: r.explanation, difficulty: r.difficulty || 'medium', source: r.source || 'pasted parser', tags: [], createdAt: Date.now(), updatedAt: Date.now(), stats: { attempts: 0, correct: 0, wrong: 0 }, bookmarked: false }; await dbPut('questions', q); }
    window.approveParsedQuestions = async () => { syncParserAssignment(); const rows = parser.rows.filter(r => r.keep && !r.issues.length); if (!parser.subjectId || !parser.topicId) {
 if (typeof toast === 'function') toast('Choose a subject and topic before approving'); return; } if (!rows.length) { if (typeof toast === 'function') toast('No valid questions ready'); return; } for (const r of rows) await saveQuestionRow(r); CACHE.questions = await dbGetAll('questions'); if (typeof toast === 'function') toast(rows.length + ' questions added to Question Bank'); navigate('question-bank/topic/' + parser.topicId); };
  function downloadFile(name, content, type) { const blob = new Blob([content], { type }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); }
  function rowsToCsv(rows) { const quote = x => '"' + String(x ?? '').replace(/"/g, '""') + '"'; return ['question,optionA,optionB,optionC,optionD,correctAnswer,explanation,subjectId,topicId,difficulty,source', ...rows.map(r => [r.question, ...r.options, r.correctAnswer >= 0 ? String.fromCharCode(65 + r.correctAnswer) : '', r.explanation, r.subjectId, r.topicId, r.difficulty, r.source].map(quote).join(','))].join('\n'); }
  function rowsToJson(rows) { return JSON.stringify(rows.map(r => ({ question: r.question, options: r.options, correctAnswer: r.correctAnswer, explanation: r.explanation, subjectId: r.subjectId, topicId: r.topicId, difficulty: r.difficulty, source: r.source })), null, 2); }
  window.exportParsed = format => { const rows = parser.rows.filter(r => r.keep); if (format === 'csv') downloadFile('parsed-questions.csv', rowsToCsv(rows), 'text/csv'); else downloadFile('parsed-questions.json', rowsToJson(rows), 'application/json'); };
  window.exportQuestionBank = format => { const rows = CACHE.questions.map(q => ({ question: q.question, options: q.options || [], correctAnswer: q.answerIndex ?? q.answer ?? 0, explanation: q.explanation || '', subjectId: q.subjectId || '', topicId: q.topicId || '', difficulty: q.difficulty || 'medium', source: q.source || '' })); if (format === 'csv') downloadFile('question-bank.csv', rowsToCsv(rows), 'text/csv'); else if (format === 'txt') downloadFile('question-bank.txt', rows.map((r,i) => `${i + 1}. ${r.question}\nA) ${r.options[0] || ''}\nB) ${r.options[1] || ''}\nC) ${r.options[2] || ''}\nD) ${r.options[3] || ''}\nAnswer: ${String.fromCharCode(65 + r.correctAnswer)}\nExplanation: ${r.explanation}`).join('\n\n'), 'text/plain'); else downloadFile('question-bank.json', JSON.stringify(rows, null, 2), 'application/json'); };
  window.parserImportFile = () => { const input = document.createElement('input'); input.type = 'file'; input.accept = '.json,.txt,.csv,application/json,text/plain,text/csv'; input.onchange = async () => { const file = input.files?.[0]; if (!file) return; const text = await file.text(); if (/\.json$/i.test(file.name)) { try { const data = JSON.parse(text); parser.rows = (Array.isArray(data) ? data : data.questions || []).slice(0, 1000).map((x,i) => ({ id: 'imported-' + i, question: clean(x.question), options: Array.isArray(x.options) ? x.options.slice(0,4) : [x.optionA,x.optionB,x.optionC,x.optionD].map(clean), correctAnswer: typeof x.correctAnswer === 'string' ? parseAnswer(x.correctAnswer) : Number(x.correctAnswer ?? x.answer ?? -1), answer: Number(x.correctAnswer ?? x.answer ?? -1), explanation: clean(x.explanation), subjectId: x.subjectId || parser.subjectId, topicId: x.topicId || parser.topicId, difficulty: x.difficulty || 'medium', source: x.source || 'file import', issues: [], duplicate: false, duplicateId: '', keep: true })); } catch (_) { parser.raw = text; parser.rows = parseInput(text); } } else if (/\.csv$/i.test(file.name)) { parser.rows = parseCsv(text); } else { parser.raw = text; parser.rows = parseInput(text); } duplicateRows(parser.rows); renderParserPreview(); }; input.click(); };
  function parseCsv(text) { const lines = text.split(/\r?\n/).filter(Boolean); const header = lines.shift(); return lines.slice(0, 1000).map((line,i) => { const cells = line.match(/("(?:[^"]|"")*"|[^,]*)/g)?.filter((x,j,a) => j < a.length - 1).map(x => x.replace(/^"|"$/g, '').replace(/""/g, '')) || []; const r = { id: 'csv-' + i, question: cells[0] || '', options: cells.slice(1,5), correctAnswer: parseAnswer(cells[5] || ''), answer: parseAnswer(cells[5] || ''), explanation: cells[6] || '', subjectId: cells[7] || parser.subjectId, topicId: cells[8] || parser.topicId, difficulty: cells[9] || 'medium', source: cells[10] || 'CSV import', issues: [], duplicate: false, duplicateId: '', keep: true }; if (!r.question) r.issues.push('Missing question'); if (r.options.length < 4 || r.options.some(x => !x)) r.issues.push('Missing one or more options A–D'); if (r.correctAnswer < 0) r.issues.push('Missing or unrecognized answer'); return r; }); }

  function addPhase2Entries() { return; }
  const previousRender = window.render;
  window.render = function phase2Render() { const path = Router.path || location.hash.slice(1); if (path === 'question-parser') return typeof window.renderQuestionParser === 'function' ? window.renderQuestionParser() : (parser.rows.length ? renderParserPreview() : renderParserHome()); const result = previousRender.apply(this, arguments); setTimeout(addPhase2Entries, 0); return result; };
  const style = document.createElement('style'); style.id = 'phase2-dictionary-parser-style'; style.textContent = `.p2-page{padding:14px 0 28px}.p2-head{margin-bottom:16px}.p2-back{border:0;background:none;padding:0;color:var(--emerald);font-size:14px;font-weight:800;cursor:pointer}.p2-head h1{font-size:28px;margin:5px 0;color:var(--text)}.p2-head>p{color:var(--sub);line-height:1.55;margin:6px 0}.p2-kicker{font-size:10px;letter-spacing:1.3px;font-weight:900;color:#c9795f}.p2-search{position:relative;display:flex;gap:8px;align-items:stretch;background:var(--card);border:1px solid var(--line);border-radius:17px;padding:8px;box-shadow:var(--shadow)}.p2-search input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:var(--text);font:inherit;padding:10px}.p2-primary,.p2-secondary{border:0;border-radius:11px;padding:10px 14px;font-weight:800;cursor:pointer}.p2-primary{background:var(--emerald);color:#fff}.p2-secondary{background:var(--mint);color:var(--emerald-d)}.p2-suggestions{position:absolute;top:calc(100% + 7px);left:0;right:0;background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);z-index:20;overflow:hidden}.p2-suggestions button{display:block;width:100%;padding:11px 14px;text-align:left;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--text);cursor:pointer}.p2-status,.p2-error{margin:14px 0;padding:14px;border-radius:14px;background:var(--mint);color:var(--text)}.p2-error{background:#fff5f1;border:1px solid #f2c5b5}.p2-dict-result{margin-top:16px;background:var(--card);border:1px solid var(--line);border-radius:20px;padding:16px;box-shadow:var(--shadow)}.p2-word-row{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.p2-word-row h2{font-size:31px;margin:4px 0}.p2-phonetic,.p2-muted{color:var(--sub);font-size:12px}.p2-favorite{border:1px solid var(--line);border-radius:10px;padding:9px;background:var(--bg);color:var(--sub);cursor:pointer}.p2-favorite.active{color:#bd721f;border-color:#e6bc74}.p2-dict-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:17px}.p2-dict-grid section{background:var(--bg);border-radius:14px;padding:12px;line-height:1.55}.p2-dict-grid .p2-wide{grid-column:1/-1}.p2-dict-grid h3,.p2-sources h3{font-size:13px;margin:0 0 6px;color:var(--emerald-d)}.p2-dict-grid p,.p2-dict-grid ol{font-size:13px;margin:0}.p2-dict-grid ol{padding-left:18px}.p2-example{font-style:italic}.p2-sources{margin-top:16px}.p2-sources a{display:flex;flex-direction:column;gap:3px;border-top:1px solid var(--line);padding:10px 0;text-decoration:none;color:var(--emerald-d)}.p2-sources small{font-size:11px;color:var(--sub)}.p2-section-title{display:flex;align-items:end;justify-content:space-between;margin-top:18px}.p2-section-title h3{margin:0}.p2-recent>button{display:flex;width:100%;justify-content:space-between;border:0;border-bottom:1px solid var(--line);background:transparent;padding:11px 2px;color:var(--text);cursor:pointer}.p2-recent small{color:var(--sub)}.p2-parser-tools,.p2-entry-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.p2-tool-card,.p2-entry-grid button{border:1px solid var(--line);border-radius:16px;background:var(--card);padding:15px;text-align:left;box-shadow:var(--shadow);cursor:pointer;color:var(--text)}.p2-tool-card strong,.p2-tool-card small,.p2-entry-grid button,.p2-entry-grid small{display:block}.p2-tool-card small,.p2-entry-grid small{color:var(--sub);font-size:12px;margin-top:6px;line-height:1.4}.p2-parser-note{margin-top:14px;padding:13px;border-radius:14px;background:var(--mint);font-size:12px;line-height:1.6}.p2-parser-assignment{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:12px}.p2-parser-assignment label{font-size:12px;font-weight:800;color:var(--sub)}.p2-parser-assignment select{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--text)}.p2-textarea{width:100%;box-sizing:border-box;border:1px solid var(--line);border-radius:15px;padding:13px;resize:vertical;background:var(--card);color:var(--text);font:14px/1.55 inherit}.p2-parser-actions,.p2-preview-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px;flex-wrap:wrap}.p2-preview-list{display:grid;gap:11px;margin-top:14px}.p2-preview-card{border:1px solid var(--line);border-radius:16px;background:var(--card);padding:14px;box-shadow:var(--shadow)}.p2-preview-card.has-issues{border-color:#e7b09e;background:#fffaf8}.p2-preview-card.removed{opacity:.5}.p2-preview-top{display:flex;gap:8px;align-items:center;color:var(--sub);font-size:12px}.p2-preview-top strong{color:var(--emerald-d);margin-right:auto}.p2-preview-top button{border:0;background:none;color:var(--emerald-d);cursor:pointer}.p2-preview-card h3{font-size:16px;line-height:1.45;margin:10px 0}.p2-options{display:grid;grid-template-columns:1fr 1fr;gap:6px}.p2-options span{font-size:12px;background:var(--bg);padding:8px;border-radius:8px}.p2-options span.correct{background:#e9f8ef;color:#075b3f;font-weight:800}.p2-preview-meta{font-size:11px;color:var(--sub)}.p2-issues{font-size:12px;color:#a34d36;line-height:1.5}.p2-entry-tools{margin:18px 0;padding:16px}.p2-entry-tools h3{margin:4px 0}.p2-entry-tools p{font-size:12px}@media(max-width:430px){.p2-dict-grid,.p2-parser-tools,.p2-entry-grid,.p2-parser-assignment{grid-template-columns:1fr}.p2-dict-grid .p2-wide{grid-column:auto}.p2-search{flex-wrap:wrap}.p2-search input{flex-basis:100%}.p2-primary{width:100%}.p2-word-row{flex-direction:column}.p2-favorite{align-self:flex-start}}`;
  document.head.appendChild(style);
  setTimeout(() => { try { addPhase2Entries(); } catch (_) {} }, 0);
})();
